#include "lift_system_arithmetic.hpp"
#include "primitive_field_arithmetic.hpp"
LiftPoly ib_polynomial(const Json& row){LiftPoly p;for(auto& term:row.arr){const auto& exponents=term.at("exponents");require(exponents.arr.size()==7,"inverse input monomial dimension");LiftExponent e{};for(int i=0;i<7;++i){e[i]=exponents.arr[i].integer();require(e[i]>=0&&e[i]<16,"inverse input exponent bound");}p.add(e,read_t24(term.at("coefficient")));}return p;}
struct InverseCoefficientExport {
    const PrimitiveBasis& pb;
    std::map<std::string,int> ids;
    std::vector<PBPoly> powers;
    int occurrences=0;
    explicit InverseCoefficientExport(const PrimitiveBasis& b):pb(b){}
    int insert(const T24& c){++occurrences;auto key=c.key();auto hit=ids.find(key);if(hit!=ids.end())return hit->second;auto converted=pb.to_power(c);require(pb.from_power(converted)==c,"every distinct inverse coefficient round trip");int id=int(powers.size());ids.emplace(key,id);powers.push_back(converted);return id;}
    void scan(const LiftPoly& p){for(auto& term:p.terms)insert(term.second);}
    void definitions(std::ostream& out)const{for(size_t i=0;i<powers.size();++i){out<<'c'<<i<<":=";pb_giac_poly(out,powers[i],"g");out<<";\n";}}
    void polynomial(std::ostream& out,const LiftPoly& p)const{std::array<std::string,7> names{"x1","y1","x2","y2","x3","y3","t"};out<<'(';bool any=false;for(auto& [e,c]:p.terms){if(any)out<<'+';any=true;auto found=ids.find(c.key());require(found!=ids.end(),"registered exported coefficient");out<<'c'<<found->second;for(int i=0;i<7;++i)if(e[i])out<<'*'<<names[i]<<'^'<<e[i];}if(!any)out<<'0';out<<')';}
};
int main(int argc,char** argv){try{
    require(argc==4,"usage: inverse_backend_export kernel3-study inverse-system.json output.giac");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;PrimitiveBasis pb;auto receipt=read_json(argv[2]);require(receipt.at("kernel").integer()==3&&receipt.at("heldout_triples").integer()==16&&receipt.at("equations_per_image").integer()==11,"qualified kernel3 inverse input");
    const auto& source=receipt.at("source_images").arr.at(0);require(source.at("fixture").scalar=="G"&&source.at("source_receipt_index").integer()==1,"fixed public source G selection");Values8 image{};for(int i=0;i<8;++i)image[i]=read_t24(source.at("normalized_H").arr[i]);int pivot=LiftSystem::normalize(image);require(pivot==source.at("pivot").integer(),"inverse source pivot binding");
    std::array<LiftPoly,8> h;require(receipt.at("shared_h").arr.size()==8,"eight retained inverse functions");for(int i=0;i<8;++i)h[i]=ib_polynomial(receipt.at("shared_h").arr[i]);auto omega=ib_polynomial(receipt.at("omega"));std::vector<LiftPoly> equations;for(auto& c:receipt.at("curve_equations").arr)equations.push_back(ib_polynomial(c));require(equations.size()==3,"three inverse curve equations");for(int i=0;i<8;++i)if(i!=pivot)equations.push_back(h[i]-h[pivot].scale(image[i]));equations.push_back(LiftPoly::variable(6)*h[pivot]*omega-LiftPoly(1));require(equations.size()==11,"eleven retained-source inverse equations");
    InverseCoefficientExport converted(pb);int terms=0;std::vector<int> term_counts;for(auto& p:equations){converted.scan(p);terms+=int(p.terms.size());term_counts.push_back(int(p.terms.size()));}require(!converted.powers.empty(),"nonempty inverse field export");std::cerr<<"all distinct inverse coefficients round-trip in original Fp24\n";
    std::ofstream out(argv[3]);require(bool(out),"open exact inverse backend program");out<<"taskprime:="<<prime<<";\ntaskfield:=GF(taskprime,";pb_giac_poly(out,pb.minimal,"k");out<<",[k,K,g],undef);\ng:=taskfield(k);\nprint(\"INVERSE_TYPE\",type(g));\n";converted.definitions(out);out<<"equations:=[";for(size_t i=0;i<equations.size();++i){if(i)out<<',';converted.polynomial(out,equations[i]);}out<<"];\nprint(\"INVERSE_EQUATION_COUNT\",size(equations));\nbasis:=gbasis(equations,[t,x1,y1,x2,y2,x3,y3],plex);\nprint(\"INVERSE_BASIS\",basis);\n";out.close();require(bool(out),"complete inverse backend program write");
    std::cout<<"{\"scope\":\"P192-kernel3-G-exact-inverse-backend-export\",\"standing\":\"producer-unverified\",\"kernel\":3,\"public_fixture\":\"G\",\"source_receipt_index\":1,\"pivot\":"<<pivot<<",\"equations\":11,\"variables\":[\"t\",\"x1\",\"y1\",\"x2\",\"y2\",\"x3\",\"y3\"],\"order\":\"lex\",\"coefficient_occurrences\":"<<converted.occurrences<<",\"distinct_coefficient_roundtrips\":"<<converted.powers.size()<<",\"total_terms\":"<<terms<<",\"terms_per_equation\":[";for(size_t i=0;i<term_counts.size();++i)std::cout<<(i?",":"")<<term_counts[i];std::cout<<"],\"roots_computed\":false}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
